import{_ as a,o as n,c as p,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"第五章 假设检验基础","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/05-第五章-假设检验.md","filePath":"tutorial/05-第五章-假设检验.md","lastUpdated":1785684581000}'),e={name:"tutorial/05-第五章-假设检验.md"};function o(l,s,c,i,d,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="第五章-假设检验基础" tabindex="-1">第五章 假设检验基础 <a class="header-anchor" href="#第五章-假设检验基础" aria-label="Permalink to &quot;第五章 假设检验基础&quot;">​</a></h1><h2 id="_5-1-统计推断与假设检验的基本思想" tabindex="-1">5.1 统计推断与假设检验的基本思想 <a class="header-anchor" href="#_5-1-统计推断与假设检验的基本思想" aria-label="Permalink to &quot;5.1 统计推断与假设检验的基本思想&quot;">​</a></h2><p>手里攥着一份样本，心里却惦记着总体——这是数据分析里最寻常的张力。我们不可能、也不必要把每一个个体都测量一遍，于是只能从样本出发，去推断总体的模样。假设检验，就是这套&quot;由局部看全局&quot;的推理工具中最核心的一件。</p><p>它始终在比较两种说法。一种是保守的、现状式的断言，称为<strong>零假设</strong>（null hypothesis，记作 H0）；另一种是研究者真正想支持的、带有变化意味的断言，称为<strong>备择假设</strong>（alternative hypothesis，记作 H1）。举个例子：药厂声称某种胶囊的平均装量为 500 毫克，质检员怀疑实际偏少。这时 H0 就是&quot;平均装量等于 500 毫克&quot;，H1 则是&quot;平均装量不等于（或小于）500 毫克&quot;。检验不预先相信哪一边，它只是问：如果 H0 真的成立，我们眼前这份样本出现的概率，大到让人安心，还是小到令人起疑？</p><p>背后的逻辑叫<strong>小概率原理</strong>：一件概率极小的事件，在一次试验中几乎不该发生。倘若在&quot;H0 成立&quot;的前提下，当前样本的出现概率小到了预先划定的门槛以下，我们就有理由怀疑 H0 本身站不住脚，从而转而支持 H1。注意，这不是&quot;证明了&quot;H1，而是&quot;H0 难以解释眼前的数据，所以暂且放下它&quot;。</p><p>被反复提及的 <strong>p 值</strong>，就是上面的&quot;概率&quot;本身。更准确地说，p 值是在 H0 成立的前提下，观察到当前样本、或更极端样本的概率。把它想成一份&quot;意外程度报告&quot;最贴切：p 值很小，意味着&quot;若 H0 为真，眼前这般甚至更离谱的结果本不该轻易撞见&quot;；p 值很大，则意味着&quot;这个结果在 H0 的世界里稀松平常，没什么好大惊小怪&quot;。p 值小到什么程度才算&quot;离谱&quot;？这个门槛由研究者事先定下，正是下一节要谈的显著性水平。</p><p>检验本身还分&quot;双侧&quot;与&quot;单侧&quot;两种姿态。若 H1 只笼统地说&quot;两者不相等&quot;，我们得两侧都提防，这叫双侧检验；若 H1 带着明确方向，例如&quot;装量低于标准&quot;或&quot;新法得分更高&quot;，只需盯着那一侧，这叫单侧检验。单侧把全部 α 押在一边，自然更容易在那一端达到显著，但方向必须在事前就有充分依据，不能等数据出来、看见哪边差异大再临时改口——那样等于悄悄挪动了门槛。</p><p>这里有个容易绊倒初学者的地方：p 值衡量的是&quot;证据 against H0 的强弱&quot;，而不是&quot;H1 为真的概率&quot;，更不是&quot;差异有多大&quot;。一个 tiny 的 p 值只说明&quot;不太可能纯属巧合&quot;，至于差异在现实里是否有意义，还得看效应量与专业判断。把这点想通，后面五花八门的 t 检验与非参数检验，其实都是同一套思想的不同化身。</p><h2 id="_5-2-显著性水平与第一、二类错误" tabindex="-1">5.2 显著性水平与第一、二类错误 <a class="header-anchor" href="#_5-2-显著性水平与第一、二类错误" aria-label="Permalink to &quot;5.2 显著性水平与第一、二类错误&quot;">​</a></h2><p>判定&quot;p 值小到离谱&quot;的那条红线，叫做<strong>显著性水平</strong>，习惯用 α 表示，最常用的值是 0.05。它的含义朴素直白：我们允许自己在 H0 明明为真时，却错误地把它拒之门外的风险不超过 5%。一旦 p ≤ α，就称结果&quot;在 α 水平下显著&quot;，于是拒绝 H0；反之 p &gt; α 则&quot;未能拒绝 H0&quot;——请留意，是&quot;未能拒绝&quot;而非&quot;接受了 H0&quot;，就像法庭上&quot;证据不足&quot;不等于&quot;被告清白&quot;。</p><p>任何判断都有走眼的可能，假设检验也不例外，且走眼分两种：</p><ul><li><strong>第一类错误</strong>（Type I）：H0 本为真，我们却拒绝了它。它发生的概率，恰恰就是 α。把 α 定得越低，犯这类错的可能就越小，但代价是更难发现问题。</li><li><strong>第二类错误</strong>（Type II）：H0 本为假，我们却没拒绝它。它发生的概率记作 β。与 α 相反，α 压得越低，β 往往越高——太谨慎地不肯冤枉 H0，就容易放过真正存在的差异。</li></ul><p><strong>检验功效</strong>（power）等于 1 − β，即&quot;当 H0 确实为假时，我们成功把它揪出来的概率&quot;。理想状态下，我们希望 α 小而功效大；现实中二者需要权衡，而增大样本量、减少测量误差、或选用更贴合数据结构的检验，都是抬高功效的正道。</p><p>样本量在这场权衡里举足轻重。效应量既定的情况下，样本越大，标准误越小，检验功效越高，越容易把真实存在的差异辨认出来；样本太小则常导致功效不足，即便差异客观存在，也可能因 p 值卡在门槛之外而被误读为&quot;没有差异&quot;。这也提醒我们：同样的 p 值，出现在大样本里未必令人振奋，出现在小样本里却要谨慎——后者常常只是&quot;证据还不够多&quot;，而非&quot;真的无差异&quot;。</p><p>把两类错误放进现实，意义立刻浮现。医学筛查里，宁可多喊几次&quot;假警报&quot;（第一类错误）也不愿漏掉真病人；司法定罪则极力压低&quot;冤枉好人&quot;的概率，宁可放过某些疑犯。这些取向，本质上都是在 α 与 β 之间做取舍。</p><p>还要提醒一句：显著性 ≠ 重要性。p 值很小，往往只是因为样本足够大，连微乎其微的差异也能被检出；此时真正该看的是<strong>效应量</strong>（effect size），它独立于样本规模，回答&quot;差异到底有多大&quot;。后文每一类 t 检验，我们都顺带给出效应量的线索，正是为了避免&quot;显著却无足轻重&quot;的误读。</p><h2 id="_5-3-单样本-t-检验" tabindex="-1">5.3 单样本 t 检验 <a class="header-anchor" href="#_5-3-单样本-t-检验" aria-label="Permalink to &quot;5.3 单样本 t 检验&quot;">​</a></h2><p>当我们手握一组观测值，又知道某个参考总体的均值，想判断&quot;这份样本是不是来自那个总体&quot;时，<strong>单样本 t 检验</strong>正合适。它的命令形态由一个 <code>TESTVAL=</code> 子命令触发，写法固定而简洁：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T-TEST TESTVAL=值 /VARIABLES=变量.</span></span></code></pre></div><p><code>TESTVAL=</code> 后面填的是那个已知的参考均值（待检验的 H0 值），<code>/VARIABLES=</code> 指定要检验的变量。通用子命令如 <code>/CRITERIA=CI(0.95)</code> 可调整置信区间的覆盖水平，<code>/MISSING</code> 控制缺失值的处理方式。图形界面的入口在 Analyze → Compare Means → One-Sample T Test（界面推断，手册未逐项文档化）。</p><p>下面构造一份数据：某次考试中，往届学生的总体平均分稳定在 75 分，这届抽了 10 名学生，想看看他们的水平是否偏离了这条基准线。H0 为&quot;均值等于 75&quot;，H1 为&quot;均值不等于 75&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /score.</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>78</span></span>
<span class="line"><span>82</span></span>
<span class="line"><span>71</span></span>
<span class="line"><span>76</span></span>
<span class="line"><span>80</span></span>
<span class="line"><span>73</span></span>
<span class="line"><span>85</span></span>
<span class="line"><span>79</span></span>
<span class="line"><span>74</span></span>
<span class="line"><span>77</span></span>
<span class="line"><span>END DATA.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T-TEST TESTVAL=75 /VARIABLES=score.</span></span></code></pre></div><p>PSPP 会输出一张单样本检验表，关键栏目包括样本均值、与检验值的差、t 值、自由度 df、双尾 p 值，以及均值差的 95% 置信区间。把上面这份数据的输出按栏目铺开，大致长这样：</p><table tabindex="0"><thead><tr><th>变量</th><th>样本均值</th><th>与检验值之差</th><th>t</th><th>df</th><th>双尾 p</th><th>95% CI 下限</th><th>95% CI 上限</th></tr></thead><tbody><tr><td>score</td><td>77.5</td><td>2.5</td><td>1.860</td><td>9</td><td>0.096</td><td>74.46</td><td>80.54</td></tr></tbody></table><p>就上面的数据而言，样本均值为 77.5，与 75 相差 2.5；t 值约为 1.860，自由度 df = 9，双尾 p 值约为 0.096，95% 置信区间约为 [74.46, 80.54]。</p><p>解读时先看置信区间：它整体落在 75 的上方一侧，却又跨过了 75 这个点本身。对应的 p 值 0.096 略高于常用的 α = 0.05 门槛，因此在 5% 水平上我们<strong>未能拒绝</strong> H0——也就是说，仅凭这 10 个分数，尚不足以断言本届学生已整体偏离往届基准。这个&quot;差一点就显著&quot;的案例，正是提醒读者：p 值只是连续的概率，贴着门槛的解读要格外审慎，别把 0.049 与 0.051 想成天壤之别。</p><p>另需说明，PSPP 在单样本检验中报告的 p 值默认为双尾；若研究在事前已明确只关心某一方向（如&quot;是否高于 75&quot;），可将双尾 p 值除以 2 作为单尾参考值，但方向必须事前确定，不能看了数据再选。</p><h2 id="_5-4-独立样本-t-检验" tabindex="-1">5.4 独立样本 t 检验 <a class="header-anchor" href="#_5-4-独立样本-t-检验" aria-label="Permalink to &quot;5.4 独立样本 t 检验&quot;">​</a></h2><p>若想比较<strong>两个互不相干的组</strong>在某个连续变量上的均值，例如男女生身高、两种工艺的良率评分，就该请出<strong>独立样本 t 检验</strong>。它由 <code>GROUPS=</code> 子命令触发：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T-TEST /VARIABLES=变量 /GROUPS=分组变量(值1,值2).</span></span></code></pre></div><p><code>/GROUPS=</code> 后的括号里填分组变量的两个取值，PSPP 据此把个案切成两组再做比较。图形界面入口在 Analyze → Compare Means → Independent-Samples T Test（界面推断，手册未逐项文档化）。</p><p>这份检验最贴心的设计，是输出中<strong>自动附带 Levene 方差齐性检验</strong>。t 检验默认要求两组方差相当；Levene 检验正是先替你确认这一点。它给出两行 t 检验结果：第一行&quot;假定方差齐性&quot;，第二行&quot;不假定方差齐性&quot;。判读口诀很清楚——先看 Levene 的 p 值：若 p &gt; α，认为两组方差无显著差异，采用第一行；若 p ≤ α，方差不齐，改看第二行。</p><p>构造一组对照实验数据：实验组（group=1）与对照组（group=2）各 5 例，观测某项得分。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /score group.</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>70 1</span></span>
<span class="line"><span>72 1</span></span>
<span class="line"><span>74 1</span></span>
<span class="line"><span>75 1</span></span>
<span class="line"><span>73 1</span></span>
<span class="line"><span>68 2</span></span>
<span class="line"><span>66 2</span></span>
<span class="line"><span>70 2</span></span>
<span class="line"><span>67 2</span></span>
<span class="line"><span>65 2</span></span>
<span class="line"><span>END DATA.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T-TEST /VARIABLES=score /GROUPS=group(1,2).</span></span></code></pre></div><p>本例 Levene 检验的 p 值约为 0.85，远大于 0.05，说明两组方差齐性成立，于是读取第一行：t 值约为 4.60，df = 8，双尾 p 值约为 0.002，两组均值差为 5.6，其 95% 置信区间约为 [2.80, 8.40]。p 远小于 0.05，拒绝 H0，认为两组得分存在显著差异，且效应量 Cohen&#39;s d 约为 2.9，属大效应。易错点在于：务必让 <code>GROUPS()</code> 括号里的取值与数据集中分组变量的真实取值对上，否则 PSPP 会把不属于这两组的个案忽略或报错。</p><h2 id="_5-5-配对样本-t-检验" tabindex="-1">5.5 配对样本 t 检验 <a class="header-anchor" href="#_5-5-配对样本-t-检验" aria-label="Permalink to &quot;5.5 配对样本 t 检验&quot;">​</a></h2><p>还有一种常见情形：同一批对象在接受处理前后各测一次，或一对对匹配好的个体各测一次。这时两组数据<strong>天然成对</strong>，前后两次的个体差异才是关注焦点，应当使用<strong>配对样本 t 检验</strong>，由 <code>PAIRS=</code> 子命令触发：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T-TEST /PAIRS=变量1 WITH 变量2 (PAIRED).</span></span></code></pre></div><p>这里有个务必上心的细节：<code>WITH</code> 连接的两个变量若不写 <code>(PAIRED)</code>，PSPP 会生成所有可能的变量配对组合；只有加上 <code>(PAIRED)</code>，才真正把&quot;变量1 的第 i 个个案&quot;与&quot;变量2 的第 i 个个案&quot;一一锁死，做严格的配对比较。图形界面入口在 Analyze → Compare Means → Paired-Samples T Test（界面推断，手册未逐项文档化）。</p><p>下面用一份前后测数据演示：8 名受试者训练前的指标 pre 与训练后的指标 post。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /pre post.</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>60 64</span></span>
<span class="line"><span>62 63</span></span>
<span class="line"><span>59 61</span></span>
<span class="line"><span>61 65</span></span>
<span class="line"><span>58 60</span></span>
<span class="line"><span>63 66</span></span>
<span class="line"><span>57 59</span></span>
<span class="line"><span>60 62</span></span>
<span class="line"><span>END DATA.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T-TEST /PAIRS=pre WITH post (PAIRED).</span></span></code></pre></div><p>配对检验的实质，是把每一对的前后差（post − pre）当作一个新的样本，再做单样本 t 检验，检验这些差值的均值是否为 0。本例 8 个差值的平均约为 2.5，t 值约为 6.614，df = 7，双尾 p 值小于 0.001，差值均值的 95% 置信区间约为 [1.61, 3.39]，全程落在 0 的上方。结论明确：训练后指标显著高于训练前，效应量相当可观。若当初漏写 <code>(PAIRED)</code>，系统可能把 pre 与 post 当成两组独立变量胡乱配对，结果便失去&quot;同一人前后对比&quot;的意义。</p><h2 id="_5-6-非参数检验入门" tabindex="-1">5.6 非参数检验入门 <a class="header-anchor" href="#_5-6-非参数检验入门" aria-label="Permalink to &quot;5.6 非参数检验入门&quot;">​</a></h2><p>t 检验虽好，却背着几项前提：数据近似正态、至少是连续定距变量、且最好两组方差齐。一旦样本量很小、分布明显偏斜、存在极端值，或者手里只是&quot;满意/一般/不满意&quot;这类<strong>有序分类数据</strong>，硬上 t 检验就不牢靠了。这时该转向<strong>非参数检验</strong>——它们不依赖总体的分布形状，因而更稳健，代价通常是统计功效略低。在 PSPP 里，这类方法统一收在 <code>NPAR TESTS</code> 命令之下。</p><p><code>NPAR TESTS</code> 通过不同的子命令区分具体检验，下面逐一给出语法与适用场景。</p><p><strong>拟合优度：<code>/CHISQUARE</code></strong>。用来判断一个分类变量的频数与你预期的频数是否吻合，例如掷骰子是否公平、选民意向是否均匀。可指定取值范围与期望比例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NPAR TESTS /CHISQUARE=vote(1,3) /EXPECTED=0.3,0.4,0.3.</span></span></code></pre></div><p><code>/EXPECTED=EQUAL</code> 表示期望各分类均等；也可像上面这样给出不等的期望权重。</p><p><strong>符号检验：<code>/SIGN</code></strong>。适用于配对资料，尤其当差值分布明显不对称、或数据为有序等级时。它只数&quot;正差&quot;与&quot;负差&quot;的个数，连差值大小都不依赖，因此极为稳健：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NPAR TESTS /SIGN=before WITH after (PAIRED).</span></span></code></pre></div><p><strong>Wilcoxon 配对秩检验：<code>/WILCOXON</code></strong>。同样是配对资料，但它利用了差值的大小与符号、转化为秩后检验，比符号检验更敏感；代价是假定差值围绕中位数大致对称：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NPAR TESTS /WILCOXON=before WITH after (PAIRED).</span></span></code></pre></div><p><strong>Mann–Whitney 两独立组秩和检验：<code>/MANN-WHITNEY</code></strong>。它是独立样本 t 检验的非参数替身，比较两组个案的秩和，对正态性没有要求。可缩写为 <code>M-W</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NPAR TESTS /MANN-WHITNEY=score BY group(1,2).</span></span></code></pre></div><p>括号里是分组变量及其两个取值；凡取值既非 g1 也非 g2 的个案会被自动忽略，这一点要留心。</p><p>沿用一组小数据感受它的用法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /score group.</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>55 1</span></span>
<span class="line"><span>60 1</span></span>
<span class="line"><span>58 1</span></span>
<span class="line"><span>62 1</span></span>
<span class="line"><span>59 2</span></span>
<span class="line"><span>64 2</span></span>
<span class="line"><span>61 2</span></span>
<span class="line"><span>66 2</span></span>
<span class="line"><span>END DATA.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NPAR TESTS /MANN-WHITNEY=score BY group(1,2).</span></span></code></pre></div><p>输出会给出两组的秩和、U 统计量及对应的 p 值；若 p ≤ α，便可认为两组分布位置不同。它不告诉你差了多少，只告诉你&quot;位置是否挪动了&quot;——这正是非参数方法克制而诚实的一面。</p><p><strong>正态性检验：<code>/KOLMOGOROV-SMIRNOV</code></strong>。用来考察某个变量是否服从指定的理论分布，最常拿来检查&quot;数据够不够正态&quot;，从而决定前面能不能放心用 t 检验。可缩写为 <code>K-S</code>，括号内声明分布类型与参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NPAR TESTS /KOLMOGOROV-SMIRNOV (NORMAL 75 10)=score.</span></span></code></pre></div><p>上面以均值 75、标准差 10 的正态分布为参照；括号里还能换作 <code>UNIFORM</code>、<code>POISSON</code>、<code>EXPONENTIAL</code> 等分布。若对 <code>score</code> 与 <code>age</code> 同时检验正态性，可写 <code>/KOLMOGOROV-SMIRNOV (NORMAL 3.5 2.0)=score age.</code>，其中每个变量套用各自的 mu、sigma。</p><p>除以上五项外，PSPP 手册还实现了 <code>BINOMIAL</code>、<code>COCHRAN</code>、<code>FRIEDMAN</code>、<code>KENDALL</code>、<code>KRUSKAL-WALLIS</code>、<code>MCNEMAR</code>、<code>MEDIAN</code>、<code>RUNS</code> 等非参数过程，覆盖二项比例、多相关样本、秩相关、多组独立比较、配对四格表、中位数与随机性等诸多场景，需要时可在 <code>NPAR TESTS</code> 下继续探索。图形界面的非参数入口多在 Analyze → Nonparametric Tests → …（界面推断，手册未逐项文档化）。</p><p>挑选哪一类检验，归根到底要先问三个问题：数据是独立的还是配对的？是连续定距还是有序分类？分布够不够正态、样本够不够大？把这几条理顺，t 检验与非参数检验的分工便一目了然——前者锋利却挑数据，后者温和而兜底。</p>`,63)])])}const g=a(e,[["render",o]]);export{h as __pageData,g as default};
